def mark_existing_students_verified(apps, schema_editor):
    """Accounts from v1.1.0 already had unique Student IDs. Keep them working: they count as
    verified, their ID is locked, and the ID is recorded as their first Student ID."""
    Profile = apps.get_model("core", "Profile")
    StudentIdRecord = apps.get_model("core", "StudentIdRecord")
    from django.utils import timezone
    now = timezone.now()
    for profile in Profile.objects.filter(role="student").exclude(student_id__isnull=True).exclude(student_id=""):
        profile.email_verified_at = now
        profile.student_id_locked = True
        profile.save(update_fields=["email_verified_at", "student_id_locked"])
        StudentIdRecord.objects.get_or_create(
            user_id=profile.user_id, student_id=profile.student_id, defaults={"source": "LEGACY"},
        )
    # Superusers no longer become administrators automatically; existing ones keep their role.


